input.command:
$r='<root>/repo'
foreach($b in 'main','agent/ok','agent/held'){ "== $b"; git -C $r rev-list --left-right --count refs/heads/agent/release...refs/heads/$b; git -C $r merge-base refs/heads/agent/release refs/heads/$b; git -C $r log --oneline refs/heads/agent/release..refs/heads/$b; git -C $r merge-tree --write-tree refs/heads/agent/release refs/heads/$b | Out-Null; "mt=$LASTEXITCODE" }
"tags:"; git -C $r tag; "remotes:"; git -C $r for-each-ref refs/remotes; git -C $r config --get-regexp '^branch\.'; git -C $r ls-files --others --ignored --exclude-standard --directory

